"""Draft six additional LeafCutter roles against exact primary paragraphs; preserve the existing P108 review and apply no catalog/availability change."""
import argparse,gzip,hashlib,json
from pathlib import Path
import xml.etree.ElementTree as ET
from setup_deseq2_reference import ROOT,pin,save
from collect_omics_review import paragraphs,validate_supporting_evidence,tool_matches
from biomart_catalog import load_catalog_registry

ROLES={
 'P073':dict(primary=37,version='0.2.9',context='intron-quantification-sQTL-phenotypes-and-pairwise-differential-splicing',support=[38,39],summary='Quantified pseudobulk intron usage with LeafCutter0.2.9 and prepared sQTL phenotypes with its prepare_phenotype_table.py script, filtering introns with zero counts in more than40% of samples or SD below0.005. Separately used LeafCutter0.2.7 for sex-biased differential splicing and LeafCutter for pairwise ancestry comparisons.',note='Quantification/preprocessing is reported as0.2.9, separately from sex-analysis version0.2.7. Sex models adjusted for age, sequencing center and five genotype PCs; ancestry comparisons adjusted for sex/age in Singapore, with BH FDR<0.05. The paper zero-count wording does not resolve intron-numerator versus cluster-denominator masking; the current script marks denominator<1 as missing. SAMtools pooling, RegTools0.0.1 extraction, SpliZ scores and GENCODE32 remain separate. No immutable paper revision, historical R execution or unreported default argument is inferred.'),
 'P132':dict(primary=60,version='0.2.6',context='intron-splicing-quantification-for-additive-sQTL-regression',support=[],summary='Used LeafCutter0.2.6 to quantify RNA alternative splicing before additive genetic association tests on quantile-normalized junction PSI phenotypes.',note='The downstream regression adjusted for sequencing artifacts, demographics, blood cell counts and15 leave-one-chromosome-out PSI components; COLOC was separate. The paragraph does not identify the exact LeafCutter entrypoint, preprocessing script/options or immutable revision. Do not recast the downstream additive sQTL regression as LeafCutter differential-splicing fitting, or infer that current-source preprocessing/PCA orientation reproduces the historical PSI matrix.'),
 'P157':dict(primary=44,version='0.2.7',context='splicing-quantification-before-cis-sQTL-calling-and-fine-mapping',support=[],summary='Quantified splicing levels using LeafCutter0.2.7 for an sQTL calling/fine-mapping pipeline that included15 PEER factors.',note='The study-specific pipeline used a cis-window within0.1Mb of intron-cluster centers, omitted GTEx WASP and z-score filters, and removed nominally tested clusters whose minimum P exceeded5e-8. These downstream masks, PEER adjustment, association and fine-mapping choices are not assigned to the LeafCutter clustering or differential-splicing kernel. Exact clustering/preprocessing arguments and the historical R runtime are not established by this paragraph.'),
 'P190':dict(primary=32,version=None,context='intron-cluster-splicing-representation-in-standard-sQTL-benchmark',support=[],summary='Used LeafCutter intron-cluster splicing quantification as one molecular representation in the standard sQTL benchmark across five GTEx tissues, comparing it with MAJIQ LSVs and normalized Salmon isoform expression.',note='This is actual Results-based quantification/benchmark use, rather than a generic introduction mention. The LeafCutter release, immutable revision and clustering/phenotype parameters are not reported in this paragraph. MAJIQ intron-retention representation, Salmon transcript-start/end differences, MAJIQTL models and the downstream standard-sQTL tests remain separate; LeafCutter is not credited with those event types, models or paper-specific association results.'),
 'P201':dict(primary=10,version=None,context='intron-excision-ratios-and-normalized-sQTL-phenotypes',support=[14],summary='Used LeafCutter to cluster intron excision events and calculate standardized, quantile-normalized excision ratios for sQTL phenotypes. The paper reports50reads per cluster and a500kb maximum intron length.',note='The paper labels50reads/500kb as defaults without an exact release. Keep these reported settings distinct from current30reads/100kb and the current additional per-intron threshold; they do not fully specify historical clustering. The aligned-read reference is GRCh38/Ensembl110. LeafViz annotation/visualization, QTLTools association/permutations,29 PEER factors and five genotype PCs remain separate. The text does not establish the current normalization axis, native PCA covariates, differential testing or exact script identity.'),
 'P238':dict(primary=28,version=None,context='splicing-TWAS-benchmark-comparator-with-FUSION',support=[],summary='Compared SpliTWAS associations with a LeafCutter-plus-FUSION splicing-based TWAS comparator, assessing overlapping and method-specific associated genes.',note='The Results paragraph supports the comparator role but does not establish whether LeafCutter quantification/weights were newly generated or reused, its release, clustering/preprocessing options or the trained FUSION models. Do not infer a fresh clustering run or LeafCutter differential-splicing test. The later Discussion describes general intron-event TWAS; SpliTWAS logit-transformed exon PSI and heritability-window choices are not reassigned to LeafCutter.'),
}


def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--out',required=True,type=Path);p.add_argument('--write-draft',action='store_true');a=p.parse_args();out=a.out.resolve();assert out.is_relative_to(ROOT/'build/literature-review/leafcutter-runtime') and not out.exists();out.mkdir();data=ROOT/'docs/literature/omics-2023-2026';papers=json.loads((data/'papers.json').read_bytes());reviews=json.loads((ROOT/'tools/literature/reviewed-uses.json').read_bytes())['reviews'];prior=[r for r in reviews if r['tool_id']=='leafcutter'];assert len(reviews)==960 and len(prior)==1 and prior[0]['pmcid']=='PMC10703692';prior_raw=(json.dumps(prior[0],sort_keys=True,separators=(',',':'))+'\n').encode();(out/'preserved-P108-review.json').write_bytes(prior_raw);registry={r['id']:r for r in load_catalog_registry(ROOT)};draft=[]
    for paper in papers:
        if paper['paper_id'] not in ROLES:continue
        spec=ROLES[paper['paper_id']];raw=gzip.decompress((ROOT/'build/literature-review/xml'/(paper['pmcid']+'.xml.gz')).read_bytes());assert hashlib.sha256(raw).hexdigest()==paper['xml_sha256'];root=ET.fromstring(raw);assert next(e.text for e in root.findall('front/article-meta/article-id') if e.get('pub-id-type')=='doi').lower()==paper['doi'].lower();ps=paragraphs(root);by={p['paragraph_index']:p for p in ps};primary=by[spec['primary']];review=dict(pmcid=paper['pmcid'],doi=paper['doi'],tool_id='leafcutter',evidence_paragraph_sha256=hashlib.sha256(primary['text'].encode()).hexdigest(),use_summary=spec['summary'],implementation_scope_note=spec['note'],version_reported_near_name=spec['version'],usage_context=spec['context'])
        if spec['support']:review['supporting_evidence']=[dict(paragraph_index=index,section=by[index]['section'],paragraph_sha256=hashlib.sha256(by[index]['text'].encode()).hexdigest()) for index in spec['support']]
        validate_supporting_evidence(ps,[review],registry);matched=tool_matches(ps,[registry['leafcutter']],{'leafcutter':review['evidence_paragraph_sha256']});assert len(matched)==1 and matched[0]['evidence_paragraph_index']==spec['primary'];draft.append(dict(paper_id=paper['paper_id'],primary_paragraph=spec['primary'],section=primary['section'],review=review,xml_sha256=paper['xml_sha256']))
    assert len(draft)==6 and sum(len(d['review'].get('supporting_evidence',[])) for d in draft)==3;save(out/'leafcutter-use-reviews.json',draft);target=ROOT/'tools/literature/leafcutter-use-reviews.json'
    if a.write_draft:
        if target.exists():assert target.read_bytes()==(out/'leafcutter-use-reviews.json').read_bytes()
        else:target.write_bytes((out/'leafcutter-use-reviews.json').read_bytes())
    save(out/'COMPLETED.json',dict(status='PASS_SIX_DRAFT_PRIMARY_LEAFCUTTER_ROLES_ONLY',catalog_applied=False,prior_P108_review_preserved=pin(out/'preserved-P108-review.json'),source_pin=pin(Path(__file__)),draft=pin(out/'leafcutter-use-reviews.json'),new_reviews=6,new_supporting_pointers=3,current_total_reviews=960,implementation_credit=False,whole_goal_complete=False));print('Drafted6 primary-bound LeafCutter roles and3 supports; P108/catalog/counts unchanged')


if __name__=='__main__':
    if not __debug__:raise RuntimeError('Never disable exact source/role checks')
    main()
